-- READ-ONLY annual field-availability aggregate for `old_weewx`.
-- Run each SELECT independently through Weather MCP against database_name shown above.
-- UTC calendar bounds are fixed Unix epochs; no session timezone conversion is used.
-- 20 common numeric fields per query keeps the query size bounded.

-- 2009, field batch 1
SELECT COUNT(*) AS archive_rows, MIN(dateTime) AS first_epoch, MAX(dateTime) AS last_epoch, MIN(usUnits) AS min_units, MAX(usUnits) AS max_units, COUNT(DISTINCT usUnits) AS unit_count, MIN(`interval`) AS min_interval, MAX(`interval`) AS max_interval, COUNT(DISTINCT `interval`) AS interval_count, COUNT(`barometer`) AS `n_barometer`, COUNT(`pressure`) AS `n_pressure`, COUNT(`altimeter`) AS `n_altimeter`, COUNT(`inTemp`) AS `n_inTemp`, COUNT(`outTemp`) AS `n_outTemp`, COUNT(`inHumidity`) AS `n_inHumidity`, COUNT(`outHumidity`) AS `n_outHumidity`, COUNT(`windSpeed`) AS `n_windSpeed`, COUNT(`windDir`) AS `n_windDir`, COUNT(`windGust`) AS `n_windGust`, COUNT(`windGustDir`) AS `n_windGustDir`, COUNT(`rainRate`) AS `n_rainRate`, COUNT(`rain`) AS `n_rain`, COUNT(`dewpoint`) AS `n_dewpoint`, COUNT(`windchill`) AS `n_windchill`, COUNT(`heatindex`) AS `n_heatindex`, COUNT(`ET`) AS `n_ET`, COUNT(`radiation`) AS `n_radiation`, COUNT(`UV`) AS `n_UV`, COUNT(`extraTemp1`) AS `n_extraTemp1`
FROM archive WHERE dateTime >= 1230768000 AND dateTime < 1262304000;

